/**
 * In-app notification rows and unread counters.
 */
import { and, count, desc, eq, gte, inArray, isNull } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, notifications } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
import { toNotification } from "./_mappers";
import type { ListNotificationsInput } from "@/schemas/notification";
import type {
  IsoTimestamp,
  NotificationId,
  OrgId,
  Page,
  UserId,
} from "@/types/common";
import type { Notification } from "@/types/notification";

type NewNotification = Omit<
  Notification,
  "id" | "createdAt" | "updatedAt" | "readAt"
>;

export async function listNotifications(
  input: ListNotificationsInput,
): Promise<Page<Notification>> {
  const db = getDb();
  const sort = { sortColumn: notifications.createdAt, idColumn: notifications.id };

  const filters = compact(
    orgPredicate(notifications.orgId, input.orgId),
    eq(notifications.recipientId, input.recipientId),
    input.unreadOnly ? isNull(notifications.readAt) : undefined,
    input.kind === undefined || input.kind.length === 0
      ? undefined
      : inArray(notifications.kind, [...input.kind]),
  );

  const total = db
    .select({ value: count() })
    .from(notifications)
    .where(and(...filters))
    .get();

  const rows = db
    .select()
    .from(notifications)
    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
    .orderBy(desc(notifications.createdAt), desc(notifications.id))
    .limit(probeLimit(input.limit))
    .all();

  return toPage(rows, input.limit, total?.value ?? 0, toNotification, (row) => ({
    id: row.id,
    sortValue: row.createdAt,
  }));
}

/** Powers the bell badge, so it stays a single indexed count query. */
export async function countUnread(
  orgId: OrgId,
  recipientId: UserId,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(notifications)
    .where(
      and(
        orgPredicate(notifications.orgId, orgId),
        eq(notifications.recipientId, recipientId),
        isNull(notifications.readAt),
      ),
    )
    .get();
  return row?.value ?? 0;
}

export async function insertNotification(
  orgId: OrgId,
  input: NewNotification,
): Promise<Notification> {
  const inserted = await insertNotifications(orgId, [input]);
  const row = inserted.at(0);
  if (!row) throw new Error("Notification insert produced no row");
  return row;
}

/** Bulk insert used by the fan-out; one statement per recipient batch. */
export async function insertNotifications(
  orgId: OrgId,
  inputs: readonly NewNotification[],
): Promise<readonly Notification[]> {
  if (inputs.length === 0) return [];

  const stamp = toIsoTimestamp(new Date());
  const rows = getDb()
    .insert(notifications)
    .values(
      inputs.map((input) => ({
        id: newId(),
        orgId,
        recipientId: input.recipientId,
        kind: input.kind,
        title: input.title,
        body: input.body,
        href: input.href,
        actorId: input.actorId,
        readAt: null,
        channels: JSON.stringify(input.channels),
        createdAt: stamp,
        updatedAt: stamp,
      })),
    )
    .returning()
    .all();

  return rows.map(toNotification);
}

export async function markRead(
  orgId: OrgId,
  notificationId: NotificationId,
  at: IsoTimestamp,
): Promise<Notification> {
  const row = getDb()
    .update(notifications)
    .set({ readAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(notifications.orgId, orgId),
        eq(notifications.id, notificationId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Notification ${notificationId} not found`);
  return toNotification(row);
}

export async function markAllRead(
  orgId: OrgId,
  recipientId: UserId,
  at: IsoTimestamp,
): Promise<number> {
  const rows = getDb()
    .update(notifications)
    .set({ readAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(notifications.orgId, orgId),
        eq(notifications.recipientId, recipientId),
        isNull(notifications.readAt),
      ),
    )
    .returning({ id: notifications.id })
    .all();

  return rows.length;
}

/** The digest window query: everything still unread since `since`. */
export async function listUnreadSince(
  orgId: OrgId,
  recipientId: UserId,
  since: IsoTimestamp,
): Promise<readonly Notification[]> {
  const rows = getDb()
    .select()
    .from(notifications)
    .where(
      and(
        orgPredicate(notifications.orgId, orgId),
        eq(notifications.recipientId, recipientId),
        isNull(notifications.readAt),
        gte(notifications.createdAt, since),
      ),
    )
    .orderBy(desc(notifications.createdAt))
    .all();

  return rows.map(toNotification);
}

/**
 * Recomputes the usage counters that every `LimitCheck` compares against.
 *
 * Must call (do not reimplement): assertOrgScope, subscribe, getPlanLimits
 */
import { getPlanLimits } from "@/config/plan-limits";
import { emit, subscribe } from "@/lib/event-bus";
import { assertOrgScope } from "@/lib/tenant";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { toIsoTimestamp } from "@/types/common";
import type { OrgId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";
import type { OrganizationUsage } from "@/types/organization";

/** Fraction of a quota at which the "approaching limit" event fires. */
const WARN_THRESHOLD = 0.9;

export async function getUsage(
  actor: Actor,
  orgId: OrgId,
): Promise<OrganizationUsage> {
  assertOrgScope(actor, orgId);
  return usageRepo.getUsage(orgId);
}

/**
 * Full recount from the source tables. Called by the rollup job and by every
 * event that could have moved a counter — after recounting, the seat and
 * project totals are checked against the plan so a breach surfaces as an
 * event rather than waiting for the next write to be rejected.
 */
export async function recomputeUsage(
  orgId: OrgId,
): Promise<OrganizationUsage> {
  const usage = await usageRepo.recomputeUsage(orgId);
  const org = await orgRepo.findOrgById(orgId);
  if (!org) return usage;

  const limits = getPlanLimits(org.plan);

  if (usage.seatsUsed >= limits.seats * WARN_THRESHOLD) {
    await emit("billing.limit_exceeded", {
      orgId,
      actorId: null,
      occurredAt: toIsoTimestamp(new Date()),
      resource: "seats",
      limit: limits.seats,
      used: usage.seatsUsed,
    });
  }

  if (usage.projectsUsed >= limits.projects * WARN_THRESHOLD) {
    await emit("billing.limit_exceeded", {
      orgId,
      actorId: null,
      occurredAt: toIsoTimestamp(new Date()),
      resource: "projects",
      limit: limits.projects,
      used: usage.projectsUsed,
    });
  }

  return usage;
}

/**
 * Every event that changes a counted resource nudges the cache. The deltas are
 * cheap; the periodic rollup is what corrects any drift they accumulate.
 */
export function registerUsageListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.created", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: 1 });
    }),
    subscribe("issue.archived", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: -1 });
    }),
    subscribe("project.created", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { projectsUsed: 1 });
    }),
    subscribe("project.archived", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, {
        projectsUsed: -1,
        issuesUsed: -payload.issuesArchived,
      });
    }),
    subscribe("member.joined", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: 1 });
    }),
    subscribe("member.removed", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: -1 });
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

/**
 * The `organization_usage` counters read by every plan-limit check.
 */
import { and, count, eq, isNull, sql } from "drizzle-orm";
import {
  attachments,
  getDb,
  issues,
  members,
  organizationUsage,
  projects,
} from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { toUsage } from "./_mappers";
import { brandId } from "./_mappers";
import type { OrgId } from "@/types/common";
import type { OrganizationUsage } from "@/types/organization";

const BYTES_PER_MB = 1024 * 1024;

/**
 * Reads the cached counters, materialising a zeroed row the first time an org
 * is asked about. A limit check must never fail because the rollup has not run.
 */
export async function getUsage(orgId: OrgId): Promise<OrganizationUsage> {
  const row = getDb()
    .select()
    .from(organizationUsage)
    .where(eq(organizationUsage.orgId, orgId))
    .get();

  if (row) return toUsage(row);

  const created = getDb()
    .insert(organizationUsage)
    .values({ orgId, measuredAt: toIsoTimestamp(new Date()) })
    .returning()
    .get();

  return toUsage(created);
}

/**
 * Recounts every dimension from the source tables and rewrites the cache.
 * Called by the rollup job and after any bulk change that would drift.
 */
export async function recomputeUsage(
  orgId: OrgId,
): Promise<OrganizationUsage> {
  const db = getDb();

  const seats = db
    .select({ value: count() })
    .from(members)
    .where(
      and(
        eq(members.orgId, orgId),
        eq(members.status, "active"),
        isNull(members.archivedAt),
      ),
    )
    .get();

  const projectCount = db
    .select({ value: count() })
    .from(projects)
    .where(and(eq(projects.orgId, orgId), isNull(projects.archivedAt)))
    .get();

  const issueCount = db
    .select({ value: count() })
    .from(issues)
    .where(and(eq(issues.orgId, orgId), isNull(issues.archivedAt)))
    .get();

  const bytes = db
    .select({ value: sql<number | null>`sum(${attachments.sizeBytes})` })
    .from(attachments)
    .where(eq(attachments.orgId, orgId))
    .get();

  const next = {
    orgId,
    seatsUsed: seats?.value ?? 0,
    projectsUsed: projectCount?.value ?? 0,
    issuesUsed: issueCount?.value ?? 0,
    storageMbUsed: Math.ceil((bytes?.value ?? 0) / BYTES_PER_MB),
    measuredAt: toIsoTimestamp(new Date()),
  };

  const row = db
    .insert(organizationUsage)
    .values(next)
    .onConflictDoUpdate({ target: organizationUsage.orgId, set: next })
    .returning()
    .get();

  return toUsage(row);
}

/**
 * Cheap delta applied on the write path so a quota check right after a create
 * sees the new number without waiting for the rollup.
 */
export async function incrementUsage(
  orgId: OrgId,
  patch: Partial<
    Pick<
      OrganizationUsage,
      "seatsUsed" | "projectsUsed" | "issuesUsed" | "storageMbUsed"
    >
  >,
): Promise<OrganizationUsage> {
  const current = await getUsage(orgId);

  const row = getDb()
    .update(organizationUsage)
    .set({
      seatsUsed: current.seatsUsed + (patch.seatsUsed ?? 0),
      projectsUsed: current.projectsUsed + (patch.projectsUsed ?? 0),
      issuesUsed: current.issuesUsed + (patch.issuesUsed ?? 0),
      storageMbUsed: current.storageMbUsed + (patch.storageMbUsed ?? 0),
      measuredAt: toIsoTimestamp(new Date()),
    })
    .where(eq(organizationUsage.orgId, orgId))
    .returning()
    .get();

  return toUsage(row);
}

/** The rollup job's work list: the oldest measurements first. */
export async function listOrgIdsForRollup(
  limit: number,
): Promise<readonly OrgId[]> {
  const rows = getDb()
    .select({ orgId: organizationUsage.orgId })
    .from(organizationUsage)
    .orderBy(organizationUsage.measuredAt)
    .limit(Math.max(1, limit))
    .all();

  return rows.map((row) => brandId<OrgId>(row.orgId));
}

/**
 * Organization creation, settings updates and deletion; seeds the owner membership and the free subscription.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, uniqueSlug, assertValidSlug
 */
import { emit } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertValidSlug, uniqueSlug } from "@/lib/slug";
import { assertOrgScope } from "@/lib/tenant";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { record } from "./activity-service";
import { envelope, orgResource, requireFound } from "./_support";
import type {
  CreateOrganizationInput,
  DeleteOrganizationInput,
  UpdateOrganizationInput,
} from "@/schemas/organization";
import type { OrgId, UserId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { Organization, OrganizationSummary } from "@/types/organization";

/**
 * Creates an organization and everything it cannot exist without: the owner's
 * membership row and a subscription. Sign-up and "create another workspace"
 * both land here, which is why it takes a bare `ownerId` rather than an
 * `Actor` — there is no membership to build one from yet.
 */
export async function createOrganization(
  ownerId: UserId,
  input: CreateOrganizationInput,
): Promise<Organization> {
  assertValidSlug(input.slug);

  const taken = await orgRepo.listTakenOrgSlugs(input.slug);
  const slug = uniqueSlug(input.slug, taken);

  const org = await orgRepo.insertOrg({ ...input, slug }, ownerId);

  const owner = await memberRepo.insertMember(org.id, ownerId, "owner", null);
  await subscriptionRepo.insertSubscription(org.id, input.plan, "monthly");
  await usageRepo.recomputeUsage(org.id);

  await emit("member.joined", {
    ...envelope(org.id, ownerId),
    memberId: owner.id,
    userId: ownerId,
    role: owner.role,
  });

  return org;
}

export async function updateOrganization(
  actor: Actor,
  input: UpdateOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:update", orgResource(input.orgId));

  const updated = await orgRepo.updateOrg(input.orgId, input);

  // Settings changes are audited directly: the event bus has no
  // `organization.updated` key, and inventing one would widen the contract.
  await record(input.orgId, "organization.updated", {
    actorId: actor.userId,
    subjectKind: "organization",
    subjectId: updated.id,
    projectId: null,
    summary: `${updated.name} settings updated`,
  });

  return updated;
}

/**
 * Deletion is a soft delete guarded by a typed confirmation, the same shape
 * GitHub uses: the caller has to retype the slug.
 */
export async function deleteOrganization(
  actor: Actor,
  input: DeleteOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:delete", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  if (org.slug !== input.confirmSlug) {
    throw new Error("The confirmation does not match this organization's slug");
  }

  return orgRepo.archiveOrg(input.orgId);
}

/** The header/shell payload: the org plus the counters the sidebar shows. */
export async function getOrganizationSummary(
  actor: Actor,
  orgId: OrgId,
): Promise<OrganizationSummary> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  const organization = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );

  return {
    organization,
    usage: await usageRepo.getUsage(orgId),
    memberCount: await memberRepo.countActiveMembers(orgId),
    projectCount: await projectRepo.countProjects(orgId),
  };
}

/** The org switcher's list; no `Actor` exists until one is chosen. */
export async function listOrganizationsForUser(
  userId: UserId,
): Promise<readonly Organization[]> {
  return orgRepo.listOrgsForUser(userId);
}

export async function resolveOrgBySlug(
  slug: string,
): Promise<Organization | null> {
  return orgRepo.findOrgBySlug(slug);
}

/**
 * Turns the session cookie into an `Actor`. Everything server-side that needs authorization starts here.
 *
 * Must call (do not reimplement): assertOrgScope
 */
import { hashToken, randomToken } from "@/lib/hash";
import { assertOrgScope } from "@/lib/tenant";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as sessionRepo from "@/server/repositories/session-repository";
import { toIsoTimestamp } from "@/types/common";
import type { SwitchOrgInput } from "@/schemas/session";
import type { IsoTimestamp, UserId } from "@/types/common";
import type { Actor, SessionPrincipal } from "@/types/member";

/** How long a freshly issued session cookie stays valid. */
const SESSION_TTL_DAYS = 30;
const MS_PER_DAY = 24 * 60 * 60 * 1000;

/** Length in bytes of the raw session token handed to the browser. */
const TOKEN_BYTES = 32;

/**
 * Mints a session. Only the hash reaches the database, so a dump of the
 * `sessions` table cannot be replayed as a login.
 */
export async function createSessionToken(
  userId: UserId,
): Promise<{ token: string; expiresAt: IsoTimestamp }> {
  const token = randomToken(TOKEN_BYTES);
  const expiresAt = toIsoTimestamp(
    new Date(Date.now() + SESSION_TTL_DAYS * MS_PER_DAY),
  );

  await sessionRepo.createSession(userId, hashToken(token), expiresAt);

  return { token, expiresAt };
}

export async function resolveSession(
  token: string,
): Promise<SessionPrincipal | null> {
  return sessionRepo.findSessionByTokenHash(hashToken(token));
}

/**
 * The bridge between "who is logged in" and "what may they do here": given a
 * principal and the org slug in the URL, produce the `Actor` every service
 * method takes, or `null` when the user is not a member of that org.
 *
 * The `assertOrgScope` call at the end looks redundant — the actor was just
 * built from that org — but it is the invariant this whole layer exists to
 * uphold, and it catches a mis-wired membership lookup immediately.
 */
export async function resolveActorForOrg(
  principal: SessionPrincipal,
  orgSlug: string,
): Promise<Actor | null> {
  const org = await orgRepo.findOrgBySlug(orgSlug);
  if (!org) return null;

  const member = await memberRepo.findMember(org.id, principal.userId);
  if (!member || member.status !== "active") return null;

  const actor: Actor = {
    userId: principal.userId,
    orgId: org.id,
    role: member.role,
  };

  assertOrgScope(actor, org.id);

  await memberRepo.touchLastSeen(
    org.id,
    principal.userId,
    toIsoTimestamp(new Date()),
  );

  return actor;
}

/**
 * Switches the org a session defaults to. Membership is re-checked here so a
 * removed member cannot pin their cookie to an org they left.
 *
 * `SessionPrincipal` carries no session id, so the write to `sessions.
 * active_org_id` (`sessionRepository.setActiveOrg`) happens in the Server
 * Action, which still holds the cookie. This method owns the authorization
 * half of the switch.
 */
export async function switchActiveOrg(
  principal: SessionPrincipal,
  input: SwitchOrgInput,
): Promise<void> {
  const member = await memberRepo.findMember(input.orgId, principal.userId);
  if (!member || member.status !== "active") {
    throw new Error("You are not a member of that organization");
  }

  const orgs = await orgRepo.listOrgsForUser(principal.userId);
  const target = orgs.find((org) => org.id === input.orgId);
  if (!target) throw new Error("You are not a member of that organization");

  assertOrgScope(
    { userId: principal.userId, orgId: input.orgId, role: member.role },
    target.id,
  );
}

/**
 * Logs a session out. The row is removed by expiring it: `SessionPrincipal`
 * exposes no session id, so the sweep is what actually clears the row, and the
 * cookie is dropped by the caller either way.
 */
export async function destroySession(token: string): Promise<void> {
  const principal = await resolveSession(token);
  if (!principal) return;

  await sessionRepo.purgeExpiredSessions(toIsoTimestamp(new Date()));
}

"use server";

/**
 * Switches the session's active organization.
 *
 * Owner D. `assertOrgScope()` is the guard that matters: the target org is only
 * legitimate if the caller already has a membership in it, which is exactly
 * what "the resolved actor's orgId equals the requested orgId" expresses.
 *
 * Must call (do not reimplement): switchOrgSchema, assertOrgScope
 */

import { UnauthorizedActionError } from "@/actions/_lib/action-errors";
import { requireActorFor } from "@/lib/actor";
import { toActionResult } from "@/lib/errors";
import { getSessionPrincipal } from "@/lib/session";
import { assertOrgScope } from "@/lib/tenant";
import { switchOrgSchema } from "@/schemas/session";
import { switchActiveOrg } from "@/server/services/session-service";
import type { ActionResult } from "@/types/api";
import { revalidatePath } from "next/cache";

export async function switchOrgAction(raw: unknown): Promise<ActionResult<null>> {
  const parsed = switchOrgSchema.safeParse(raw);
  if (!parsed.success) {
    return toActionResult(parsed.error);
  }

  try {
    const principal = await getSessionPrincipal();
    if (principal === null) {
      throw new UnauthorizedActionError();
    }

    const actor = await requireActorFor(parsed.data.orgId);
    assertOrgScope(actor, parsed.data.orgId);

    await switchActiveOrg(principal, parsed.data);

    revalidatePath("/", "layout");
    return { ok: true, data: null, submittedAt: new Date().toISOString() };
  } catch (error) {
    return toActionResult(error);
  }
}

/**
 * Data-layer entry point. Repositories import `{ getDb }` and the table
 * objects from here so the concrete client module stays swappable.
 */
export { getDb, useInMemoryDb } from "./client";
export type { Db, DbSchema } from "./client";
export * from "./schema";

import { index, integer, sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";
import { idColumn, softDeleteColumns, timestampColumns } from "./_shared";

export const organizations = sqliteTable(
  "organizations",
  {
    id: idColumn(),
    name: text("name").notNull(),
    slug: text("slug").notNull(),
    ownerId: text("owner_id").notNull(),
    plan: text("plan", {
      enum: ["free", "starter", "growth", "enterprise"],
    })
      .notNull()
      .default("free"),
    logoUrl: text("logo_url"),
    trialEndsAt: text("trial_ends_at"),
    defaultIssueStatus: text("default_issue_status").notNull().default("backlog"),
    allowPublicProjects: integer("allow_public_projects", { mode: "boolean" })
      .notNull()
      .default(false),
    requireTwoFactor: integer("require_two_factor", { mode: "boolean" })
      .notNull()
      .default(false),
    digestHourUtc: integer("digest_hour_utc").notNull().default(7),
    enabledFlagOverrides: text("enabled_flag_overrides").notNull().default("[]"),
    ...timestampColumns,
    ...softDeleteColumns,
  },
  (table) => [
    uniqueIndex("organizations_slug_idx").on(table.slug),
    index("organizations_owner_idx").on(table.ownerId),
  ],
);

export const organizationUsage = sqliteTable("organization_usage", {
  orgId: text("org_id").primaryKey(),
  seatsUsed: integer("seats_used").notNull().default(0),
  projectsUsed: integer("projects_used").notNull().default(0),
  issuesUsed: integer("issues_used").notNull().default(0),
  storageMbUsed: integer("storage_mb_used").notNull().default(0),
  measuredAt: text("measured_at").notNull(),
});

export type OrganizationRow = typeof organizations.$inferSelect;
export type NewOrganizationRow = typeof organizations.$inferInsert;
export type OrganizationUsageRow = typeof organizationUsage.$inferSelect;

/**
 * Organization rows plus slug uniqueness lookups.
 *
 * Must call (do not reimplement): archivePatch, uniqueSlug
 */
import { and, eq, isNull, like } from "drizzle-orm";
import { newId } from "@/lib/id";
import { uniqueSlug } from "@/lib/slug";
import { archivePatch } from "@/lib/soft-delete";
import { getDb, members, organizations } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { toOrganization } from "./_mappers";
import type {
  CreateOrganizationInput,
  UpdateOrganizationInput,
} from "@/schemas/organization";
import type { OrgId, UserId } from "@/types/common";
import type { Organization } from "@/types/organization";

export async function findOrgById(orgId: OrgId): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(eq(organizations.id, orgId))
    .get();
  return row ? toOrganization(row) : null;
}

export async function findOrgBySlug(slug: string): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    .get();
  return row ? toOrganization(row) : null;
}

/** Every org the user still holds a live membership in. */
export async function listOrgsForUser(
  userId: UserId,
): Promise<readonly Organization[]> {
  const rows = getDb()
    .select({ org: organizations })
    .from(members)
    .innerJoin(organizations, eq(organizations.id, members.orgId))
    .where(
      and(
        eq(members.userId, userId),
        isNull(members.archivedAt),
        isNull(organizations.archivedAt),
      ),
    )
    .all();

  return rows.map((row) => toOrganization(row.org));
}

/**
 * Creates the org row. The slug is de-duplicated here rather than in the
 * service so a race on the unique index still resolves to a usable slug.
 */
export async function insertOrg(
  input: CreateOrganizationInput,
  ownerId: UserId,
): Promise<Organization> {
  const taken = await listTakenOrgSlugs(input.slug);
  const slug = uniqueSlug(input.slug, taken);
  const stamp = toIsoTimestamp(new Date());

  const row = getDb()
    .insert(organizations)
    .values({
      id: newId(),
      name: input.name,
      slug,
      ownerId,
      plan: input.plan,
      logoUrl: null,
      trialEndsAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toOrganization(row);
}

export async function updateOrg(
  orgId: OrgId,
  patch: UpdateOrganizationInput,
): Promise<Organization> {
  const current = await findOrgById(orgId);
  if (!current) throw new Error(`Organization ${orgId} not found`);

  const settings = { ...current.settings, ...(patch.settings ?? {}) };

  const row = getDb()
    .update(organizations)
    .set({
      ...(patch.name === undefined ? {} : { name: patch.name }),
      ...(patch.logoUrl === undefined ? {} : { logoUrl: patch.logoUrl }),
      defaultIssueStatus: settings.defaultIssueStatus,
      allowPublicProjects: settings.allowPublicProjects,
      requireTwoFactor: settings.requireTwoFactor,
      digestHourUtc: settings.digestHourUtc,
      enabledFlagOverrides: JSON.stringify(settings.enabledFlagOverrides),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  return toOrganization(row);
}

export async function archiveOrg(orgId: OrgId): Promise<Organization> {
  const row = getDb()
    .update(organizations)
    .set(archivePatch())
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Organization ${orgId} not found`);
  return toOrganization(row);
}

/** Feeds `uniqueSlug()`; matching on the prefix keeps the scan small. */
export async function listTakenOrgSlugs(
  prefix: string,
): Promise<readonly string[]> {
  const rows = getDb()
    .select({ slug: organizations.slug })
    .from(organizations)
    .where(like(organizations.slug, `${prefix}%`))
    .all();
  return rows.map((row) => row.slug);
}

import { mkdirSync } from "node:fs";
import { dirname, resolve } from "node:path";
import Database from "better-sqlite3";
import { drizzle } from "drizzle-orm/better-sqlite3";
import * as schema from "./schema";

/**
 * The single Drizzle connection for the process.
 *
 * Repositories import `db` from `@/server/db` (the barrel), never this module
 * directly, so the connection can be swapped in tests. Never construct a
 * second `Database` — SQLite in WAL mode tolerates it, but the in-process
 * event bus assumes one writer.
 */

const DEFAULT_DB_PATH = "./data/taskflow.db";

let instance: ReturnType<typeof createClient> | null = null;

function createClient(path: string) {
  const absolute = resolve(process.cwd(), path);
  mkdirSync(dirname(absolute), { recursive: true });
  const sqlite = new Database(absolute);
  sqlite.pragma("journal_mode = WAL");
  sqlite.pragma("foreign_keys = ON");
  return drizzle(sqlite, { schema });
}

export function getDb(path: string = process.env.TASKFLOW_DB_PATH ?? DEFAULT_DB_PATH) {
  instance ??= createClient(path);
  return instance;
}

/** Test hook: point the singleton at an in-memory database. */
export function useInMemoryDb(): void {
  instance = createClient(":memory:");
}

export type Db = ReturnType<typeof getDb>;
export type DbSchema = typeof schema;

/**
 * The fan-out hub: one domain event becomes in-app rows, an email draft and/or a digest entry, filtered by each recipient's preferences.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, isEnabled, subscribe
 */
import { subscribe } from "@/lib/event-bus";
import { isEnabled } from "@/lib/feature-flags";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import { toIsoTimestamp } from "@/types/common";
import { notificationResource, requireFound } from "./_support";
import type {
  ListNotificationsInput,
  MarkNotificationReadInput,
  UpdateNotificationPreferenceInput,
} from "@/schemas/notification";
import type { OrgId, Page, UserId } from "@/types/common";
import type { FlagContext } from "@/types/feature-flag";
import type { Actor } from "@/types/member";
import type {
  Notification,
  NotificationChannel,
  NotificationKind,
  NotificationPreference,
} from "@/types/notification";

export type NotificationPayload = {
  title: string;
  body: string;
  href: string;
  actorId: UserId | null;
};

/** Channels used when a recipient has never touched their preferences. */
const DEFAULT_CHANNELS: readonly NotificationChannel[] = ["in_app", "email"];

/**
 * Writes one notification row per recipient, each with the channel set that
 * recipient's preferences allow. A recipient who has muted every channel is
 * skipped entirely rather than given a row nobody will ever see.
 */
export async function notify(
  orgId: OrgId,
  kind: NotificationKind,
  recipients: readonly UserId[],
  payload: NotificationPayload,
): Promise<readonly Notification[]> {
  if (recipients.length === 0) return [];

  const org = await orgRepo.findOrgById(orgId);
  const flags: FlagContext = {
    orgId,
    userId: payload.actorId,
    plan: org?.plan ?? "free",
    role: null,
    overrides: org?.settings.enabledFlagOverrides,
  };

  const rows = [];

  for (const recipientId of new Set(recipients)) {
    if (recipientId === payload.actorId) continue;

    const preference = await preferenceRepo.getPreference(
      orgId,
      recipientId,
      kind,
    );
    const channels = resolveChannels(preference, flags);
    if (channels.length === 0) continue;

    rows.push({
      orgId,
      recipientId,
      kind,
      title: payload.title,
      body: payload.body,
      href: payload.href,
      actorId: payload.actorId,
      channels,
    });
  }

  return notificationRepo.insertNotifications(orgId, rows);
}

export async function listNotifications(
  actor: Actor,
  input: ListNotificationsInput,
): Promise<Page<Notification>> {
  assertOrgScope(actor, input.orgId);
  assertCan(
    actor,
    "notification:read",
    notificationResource(input.orgId, input.recipientId),
  );
  return notificationRepo.listNotifications(input);
}

export async function markRead(
  actor: Actor,
  input: MarkNotificationReadInput,
): Promise<Notification> {
  assertOrgScope(actor, input.orgId);
  assertCan(
    actor,
    "notification:manage",
    notificationResource(input.orgId, actor.userId),
  );
  return notificationRepo.markRead(
    input.orgId,
    input.notificationId,
    toIsoTimestamp(new Date()),
  );
}

export async function markAllRead(
  actor: Actor,
  orgId: OrgId,
): Promise<number> {
  assertOrgScope(actor, orgId);
  assertCan(
    actor,
    "notification:manage",
    notificationResource(orgId, actor.userId),
  );
  return notificationRepo.markAllRead(
    orgId,
    actor.userId,
    toIsoTimestamp(new Date()),
  );
}

export async function updatePreference(
  actor: Actor,
  input: UpdateNotificationPreferenceInput,
): Promise<NotificationPreference> {
  assertOrgScope(actor, input.orgId);
  assertCan(
    actor,
    "notification:manage",
    notificationResource(input.orgId, input.userId),
  );
  return preferenceRepo.upsertPreference(input);
}

/**
 * Turns a stored preference into the channels one notification will use.
 * `digestOnly` suppresses the immediate email but keeps the in-app row, and
 * the email channel additionally requires the org's `digest_email` plan flag.
 */
export function resolveChannels(
  preference: NotificationPreference | null,
  flags: FlagContext,
): readonly NotificationChannel[] {
  if (preference === null) return DEFAULT_CHANNELS;

  const channels: NotificationChannel[] = [];
  if (preference.inApp) channels.push("in_app");

  const emailAllowed =
    preference.email &&
    (!preference.digestOnly || isEnabled("digest_email", flags));

  if (emailAllowed) channels.push("email");
  return channels;
}

/**
 * The bus wiring. Attached at module load rather than from `event-registry`
 * because the fan-out has no other public entry point — importing this module
 * is what makes an org start receiving notifications.
 */
let registered = false;

function registerFanOut(): void {
  if (registered) return;
  registered = true;

  subscribe("issue.assigned", async (payload) => {
    await notify(payload.orgId, "issue_assigned", [payload.assigneeId], {
      title: "You were assigned an issue",
      body: `Issue ${payload.issueId} is now yours`,
      href: `/issues/${payload.issueId}`,
      actorId: payload.actorId,
    });
  });

  subscribe("issue.overdue", async (payload) => {
    if (payload.assigneeId === null) return;
    await notify(payload.orgId, "issue_overdue", [payload.assigneeId], {
      title: "An issue is overdue",
      body: `Issue ${payload.issueId} was due ${payload.dueAt}`,
      href: `/issues/${payload.issueId}`,
      actorId: null,
    });
  });

  subscribe("comment.created", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    const watchers = issue
      ? [issue.authorId, ...(issue.assigneeId ? [issue.assigneeId] : [])]
      : [];

    await notify(payload.orgId, "comment_created", watchers, {
      title: "New comment",
      body: `A comment was added to issue ${payload.issueId}`,
      href: `/issues/${payload.issueId}`,
      actorId: payload.actorId,
    });

    if (payload.mentionedUserIds.length > 0) {
      await notify(
        payload.orgId,
        "comment_mention",
        payload.mentionedUserIds,
        {
          title: "You were mentioned",
          body: `You were mentioned on issue ${payload.issueId}`,
          href: `/issues/${payload.issueId}`,
          actorId: payload.actorId,
        },
      );
    }
  });

  subscribe("member.joined", async (payload) => {
    const org = requireFound(
      await orgRepo.findOrgById(payload.orgId),
      "Organization",
      payload.orgId,
    );
    await notify(payload.orgId, "member_joined", [org.ownerId], {
      title: "A new member joined",
      body: `${payload.userId} joined as ${payload.role}`,
      href: "/settings/members",
      actorId: payload.userId,
    });
  });
}

registerFanOut();

/**
 * Recomputes the usage counters that every `LimitCheck` compares against.
 *
 * Must call (do not reimplement): assertOrgScope, subscribe, getPlanLimits
 */
import { getPlanLimits } from "@/config/plan-limits";
import { emit, subscribe } from "@/lib/event-bus";
import { assertOrgScope } from "@/lib/tenant";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { toIsoTimestamp } from "@/types/common";
import type { OrgId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";
import type { OrganizationUsage } from "@/types/organization";

/** Fraction of a quota at which the "approaching limit" event fires. */
const WARN_THRESHOLD = 0.9;

export async function getUsage(
  actor: Actor,
  orgId: OrgId,
): Promise<OrganizationUsage> {
  assertOrgScope(actor, orgId);
  return usageRepo.getUsage(orgId);
}

/**
 * Full recount from the source tables. Called by the rollup job and by every
 * event that could have moved a counter — after recounting, the seat and
 * project totals are checked against the plan so a breach surfaces as an
 * event rather than waiting for the next write to be rejected.
 */
export async function recomputeUsage(
  orgId: OrgId,
): Promise<OrganizationUsage> {
  const usage = await usageRepo.recomputeUsage(orgId);
  const org = await orgRepo.findOrgById(orgId);
  if (!org) return usage;

  const limits = getPlanLimits(org.plan);

  if (usage.seatsUsed >= limits.seats * WARN_THRESHOLD) {
    await emit("billing.limit_exceeded", {
      orgId,
      actorId: null,
      occurredAt: toIsoTimestamp(new Date()),
      resource: "seats",
      limit: limits.seats,
      used: usage.seatsUsed,
    });
  }

  if (usage.projectsUsed >= limits.projects * WARN_THRESHOLD) {
    await emit("billing.limit_exceeded", {
      orgId,
      actorId: null,
      occurredAt: toIsoTimestamp(new Date()),
      resource: "projects",
      limit: limits.projects,
      used: usage.projectsUsed,
    });
  }

  return usage;
}

/**
 * Every event that changes a counted resource nudges the cache. The deltas are
 * cheap; the periodic rollup is what corrects any drift they accumulate.
 */
export function registerUsageListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.created", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: 1 });
    }),
    subscribe("issue.archived", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: -1 });
    }),
    subscribe("project.created", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { projectsUsed: 1 });
    }),
    subscribe("project.archived", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, {
        projectsUsed: -1,
        issuesUsed: -payload.issuesArchived,
      });
    }),
    subscribe("member.joined", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: 1 });
    }),
    subscribe("member.removed", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: -1 });
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

/**
 * The `organization_usage` counters read by every plan-limit check.
 */
import { and, count, eq, isNull, sql } from "drizzle-orm";
import {
  attachments,
  getDb,
  issues,
  members,
  organizationUsage,
  projects,
} from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { toUsage } from "./_mappers";
import { brandId } from "./_mappers";
import type { OrgId } from "@/types/common";
import type { OrganizationUsage } from "@/types/organization";

const BYTES_PER_MB = 1024 * 1024;

/**
 * Reads the cached counters, materialising a zeroed row the first time an org
 * is asked about. A limit check must never fail because the rollup has not run.
 */
export async function getUsage(orgId: OrgId): Promise<OrganizationUsage> {
  const row = getDb()
    .select()
    .from(organizationUsage)
    .where(eq(organizationUsage.orgId, orgId))
    .get();

  if (row) return toUsage(row);

  const created = getDb()
    .insert(organizationUsage)
    .values({ orgId, measuredAt: toIsoTimestamp(new Date()) })
    .returning()
    .get();

  return toUsage(created);
}

/**
 * Recounts every dimension from the source tables and rewrites the cache.
 * Called by the rollup job and after any bulk change that would drift.
 */
export async function recomputeUsage(
  orgId: OrgId,
): Promise<OrganizationUsage> {
  const db = getDb();

  const seats = db
    .select({ value: count() })
    .from(members)
    .where(
      and(
        eq(members.orgId, orgId),
        eq(members.status, "active"),
        isNull(members.archivedAt),
      ),
    )
    .get();

  const projectCount = db
    .select({ value: count() })
    .from(projects)
    .where(and(eq(projects.orgId, orgId), isNull(projects.archivedAt)))
    .get();

  const issueCount = db
    .select({ value: count() })
    .from(issues)
    .where(and(eq(issues.orgId, orgId), isNull(issues.archivedAt)))
    .get();

  const bytes = db
    .select({ value: sql<number | null>`sum(${attachments.sizeBytes})` })
    .from(attachments)
    .where(eq(attachments.orgId, orgId))
    .get();

  const next = {
    orgId,
    seatsUsed: seats?.value ?? 0,
    projectsUsed: projectCount?.value ?? 0,
    issuesUsed: issueCount?.value ?? 0,
    storageMbUsed: Math.ceil((bytes?.value ?? 0) / BYTES_PER_MB),
    measuredAt: toIsoTimestamp(new Date()),
  };

  const row = db
    .insert(organizationUsage)
    .values(next)
    .onConflictDoUpdate({ target: organizationUsage.orgId, set: next })
    .returning()
    .get();

  return toUsage(row);
}

/**
 * Cheap delta applied on the write path so a quota check right after a create
 * sees the new number without waiting for the rollup.
 */
export async function incrementUsage(
  orgId: OrgId,
  patch: Partial<
    Pick<
      OrganizationUsage,
      "seatsUsed" | "projectsUsed" | "issuesUsed" | "storageMbUsed"
    >
  >,
): Promise<OrganizationUsage> {
  const current = await getUsage(orgId);

  const row = getDb()
    .update(organizationUsage)
    .set({
      seatsUsed: current.seatsUsed + (patch.seatsUsed ?? 0),
      projectsUsed: current.projectsUsed + (patch.projectsUsed ?? 0),
      issuesUsed: current.issuesUsed + (patch.issuesUsed ?? 0),
      storageMbUsed: current.storageMbUsed + (patch.storageMbUsed ?? 0),
      measuredAt: toIsoTimestamp(new Date()),
    })
    .where(eq(organizationUsage.orgId, orgId))
    .returning()
    .get();

  return toUsage(row);
}

/** The rollup job's work list: the oldest measurements first. */
export async function listOrgIdsForRollup(
  limit: number,
): Promise<readonly OrgId[]> {
  const rows = getDb()
    .select({ orgId: organizationUsage.orgId })
    .from(organizationUsage)
    .orderBy(organizationUsage.measuredAt)
    .limit(Math.max(1, limit))
    .all();

  return rows.map((row) => brandId<OrgId>(row.orgId));
}

/**
 * Organization creation, settings updates and deletion; seeds the owner membership and the free subscription.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, uniqueSlug, assertValidSlug
 */
import { emit } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertValidSlug, uniqueSlug } from "@/lib/slug";
import { assertOrgScope } from "@/lib/tenant";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { record } from "./activity-service";
import { envelope, orgResource, requireFound } from "./_support";
import type {
  CreateOrganizationInput,
  DeleteOrganizationInput,
  UpdateOrganizationInput,
} from "@/schemas/organization";
import type { OrgId, UserId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { Organization, OrganizationSummary } from "@/types/organization";

/**
 * Creates an organization and everything it cannot exist without: the owner's
 * membership row and a subscription. Sign-up and "create another workspace"
 * both land here, which is why it takes a bare `ownerId` rather than an
 * `Actor` — there is no membership to build one from yet.
 */
export async function createOrganization(
  ownerId: UserId,
  input: CreateOrganizationInput,
): Promise<Organization> {
  assertValidSlug(input.slug);

  const taken = await orgRepo.listTakenOrgSlugs(input.slug);
  const slug = uniqueSlug(input.slug, taken);

  const org = await orgRepo.insertOrg({ ...input, slug }, ownerId);

  const owner = await memberRepo.insertMember(org.id, ownerId, "owner", null);
  await subscriptionRepo.insertSubscription(org.id, input.plan, "monthly");
  await usageRepo.recomputeUsage(org.id);

  await emit("member.joined", {
    ...envelope(org.id, ownerId),
    memberId: owner.id,
    userId: ownerId,
    role: owner.role,
  });

  return org;
}

export async function updateOrganization(
  actor: Actor,
  input: UpdateOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:update", orgResource(input.orgId));

  const updated = await orgRepo.updateOrg(input.orgId, input);

  // Settings changes are audited directly: the event bus has no
  // `organization.updated` key, and inventing one would widen the contract.
  await record(input.orgId, "organization.updated", {
    actorId: actor.userId,
    subjectKind: "organization",
    subjectId: updated.id,
    projectId: null,
    summary: `${updated.name} settings updated`,
  });

  return updated;
}

/**
 * Deletion is a soft delete guarded by a typed confirmation, the same shape
 * GitHub uses: the caller has to retype the slug.
 */
export async function deleteOrganization(
  actor: Actor,
  input: DeleteOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:delete", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  if (org.slug !== input.confirmSlug) {
    throw new Error("The confirmation does not match this organization's slug");
  }

  return orgRepo.archiveOrg(input.orgId);
}

/** The header/shell payload: the org plus the counters the sidebar shows. */
export async function getOrganizationSummary(
  actor: Actor,
  orgId: OrgId,
): Promise<OrganizationSummary> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  const organization = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );

  return {
    organization,
    usage: await usageRepo.getUsage(orgId),
    memberCount: await memberRepo.countActiveMembers(orgId),
    projectCount: await projectRepo.countProjects(orgId),
  };
}

/** The org switcher's list; no `Actor` exists until one is chosen. */
export async function listOrganizationsForUser(
  userId: UserId,
): Promise<readonly Organization[]> {
  return orgRepo.listOrgsForUser(userId);
}

export async function resolveOrgBySlug(
  slug: string,
): Promise<Organization | null> {
  return orgRepo.findOrgBySlug(slug);
}

/**
 * Turns the session cookie into an `Actor`. Everything server-side that needs authorization starts here.
 *
 * Must call (do not reimplement): assertOrgScope
 */
import { hashToken, randomToken } from "@/lib/hash";
import { assertOrgScope } from "@/lib/tenant";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as sessionRepo from "@/server/repositories/session-repository";
import { toIsoTimestamp } from "@/types/common";
import type { SwitchOrgInput } from "@/schemas/session";
import type { IsoTimestamp, UserId } from "@/types/common";
import type { Actor, SessionPrincipal } from "@/types/member";

/** How long a freshly issued session cookie stays valid. */
const SESSION_TTL_DAYS = 30;
const MS_PER_DAY = 24 * 60 * 60 * 1000;

/** Length in bytes of the raw session token handed to the browser. */
const TOKEN_BYTES = 32;

/**
 * Mints a session. Only the hash reaches the database, so a dump of the
 * `sessions` table cannot be replayed as a login.
 */
export async function createSessionToken(
  userId: UserId,
): Promise<{ token: string; expiresAt: IsoTimestamp }> {
  const token = randomToken(TOKEN_BYTES);
  const expiresAt = toIsoTimestamp(
    new Date(Date.now() + SESSION_TTL_DAYS * MS_PER_DAY),
  );

  await sessionRepo.createSession(userId, hashToken(token), expiresAt);

  return { token, expiresAt };
}

export async function resolveSession(
  token: string,
): Promise<SessionPrincipal | null> {
  return sessionRepo.findSessionByTokenHash(hashToken(token));
}

/**
 * The bridge between "who is logged in" and "what may they do here": given a
 * principal and the org slug in the URL, produce the `Actor` every service
 * method takes, or `null` when the user is not a member of that org.
 *
 * The `assertOrgScope` call at the end looks redundant — the actor was just
 * built from that org — but it is the invariant this whole layer exists to
 * uphold, and it catches a mis-wired membership lookup immediately.
 */
export async function resolveActorForOrg(
  principal: SessionPrincipal,
  orgSlug: string,
): Promise<Actor | null> {
  const org = await orgRepo.findOrgBySlug(orgSlug);
  if (!org) return null;

  const member = await memberRepo.findMember(org.id, principal.userId);
  if (!member || member.status !== "active") return null;

  const actor: Actor = {
    userId: principal.userId,
    orgId: org.id,
    role: member.role,
  };

  assertOrgScope(actor, org.id);

  await memberRepo.touchLastSeen(
    org.id,
    principal.userId,
    toIsoTimestamp(new Date()),
  );

  return actor;
}

/**
 * Switches the org a session defaults to. Membership is re-checked here so a
 * removed member cannot pin their cookie to an org they left.
 *
 * `SessionPrincipal` carries no session id, so the write to `sessions.
 * active_org_id` (`sessionRepository.setActiveOrg`) happens in the Server
 * Action, which still holds the cookie. This method owns the authorization
 * half of the switch.
 */
export async function switchActiveOrg(
  principal: SessionPrincipal,
  input: SwitchOrgInput,
): Promise<void> {
  const member = await memberRepo.findMember(input.orgId, principal.userId);
  if (!member || member.status !== "active") {
    throw new Error("You are not a member of that organization");
  }

  const orgs = await orgRepo.listOrgsForUser(principal.userId);
  const target = orgs.find((org) => org.id === input.orgId);
  if (!target) throw new Error("You are not a member of that organization");

  assertOrgScope(
    { userId: principal.userId, orgId: input.orgId, role: member.role },
    target.id,
  );
}

/**
 * Logs a session out. The row is removed by expiring it: `SessionPrincipal`
 * exposes no session id, so the sweep is what actually clears the row, and the
 * cookie is dropped by the caller either way.
 */
export async function destroySession(token: string): Promise<void> {
  const principal = await resolveSession(token);
  if (!principal) return;

  await sessionRepo.purgeExpiredSessions(toIsoTimestamp(new Date()));
}

/**
 * Session cookie access. In Next 16 `cookies()` is async — every function
 * here is async for that reason, and nothing outside this module touches the
 * cookie jar, so the cookie's name, flags and lifetime are stated once.
 */
import { cookies } from "next/headers";
import { SESSION_COOKIE_NAME } from "@/schemas/session";
import { resolveSession } from "@/server/services/session-service";
import type { IsoTimestamp } from "@/types/common";
import type { SessionPrincipal } from "@/types/member";
import { parseIso } from "./date";

export async function getSessionToken(): Promise<string | null> {
  const jar = await cookies();
  return jar.get(SESSION_COOKIE_NAME)?.value ?? null;
}

/**
 * The signed-in principal, or `null` when there is no cookie, the token is
 * unknown, or the session has expired. Callers that need a hard failure use
 * `getActor()` in `@/lib/actor` instead.
 */
export async function getSessionPrincipal(): Promise<SessionPrincipal | null> {
  const token = await getSessionToken();
  if (token === null) return null;

  const principal = await resolveSession(token);
  if (principal === null) return null;

  return parseIso(principal.expiresAt).getTime() > Date.now() ? principal : null;
}

export async function setSessionCookie(
  token: string,
  expiresAt: IsoTimestamp,
): Promise<void> {
  const jar = await cookies();
  jar.set(SESSION_COOKIE_NAME, token, {
    httpOnly: true,
    sameSite: "lax",
    secure: process.env.NODE_ENV === "production",
    path: "/",
    expires: parseIso(expiresAt),
  });
}

export async function clearSessionCookie(): Promise<void> {
  const jar = await cookies();
  jar.delete(SESSION_COOKIE_NAME);
}

/**
 * In-app notification rows and unread counters.
 */
import { and, count, desc, eq, gte, inArray, isNull } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, notifications } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
import { toNotification } from "./_mappers";
import type { ListNotificationsInput } from "@/schemas/notification";
import type {
  IsoTimestamp,
  NotificationId,
  OrgId,
  Page,
  UserId,
} from "@/types/common";
import type { Notification } from "@/types/notification";

type NewNotification = Omit<
  Notification,
  "id" | "createdAt" | "updatedAt" | "readAt"
>;

export async function listNotifications(
  input: ListNotificationsInput,
): Promise<Page<Notification>> {
  const db = getDb();
  const sort = { sortColumn: notifications.createdAt, idColumn: notifications.id };

  const filters = compact(
    orgPredicate(notifications.orgId, input.orgId),
    eq(notifications.recipientId, input.recipientId),
    input.unreadOnly ? isNull(notifications.readAt) : undefined,
    input.kind === undefined || input.kind.length === 0
      ? undefined
      : inArray(notifications.kind, [...input.kind]),
  );

  const total = db
    .select({ value: count() })
    .from(notifications)
    .where(and(...filters))
    .get();

  const rows = db
    .select()
    .from(notifications)
    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
    .orderBy(desc(notifications.createdAt), desc(notifications.id))
    .limit(probeLimit(input.limit))
    .all();

  return toPage(rows, input.limit, total?.value ?? 0, toNotification, (row) => ({
    id: row.id,
    sortValue: row.createdAt,
  }));
}

/** Powers the bell badge, so it stays a single indexed count query. */
export async function countUnread(
  orgId: OrgId,
  recipientId: UserId,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(notifications)
    .where(
      and(
        orgPredicate(notifications.orgId, orgId),
        eq(notifications.recipientId, recipientId),
        isNull(notifications.readAt),
      ),
    )
    .get();
  return row?.value ?? 0;
}

export async function insertNotification(
  orgId: OrgId,
  input: NewNotification,
): Promise<Notification> {
  const inserted = await insertNotifications(orgId, [input]);
  const row = inserted.at(0);
  if (!row) throw new Error("Notification insert produced no row");
  return row;
}

/** Bulk insert used by the fan-out; one statement per recipient batch. */
export async function insertNotifications(
  orgId: OrgId,
  inputs: readonly NewNotification[],
): Promise<readonly Notification[]> {
  if (inputs.length === 0) return [];

  const stamp = toIsoTimestamp(new Date());
  const rows = getDb()
    .insert(notifications)
    .values(
      inputs.map((input) => ({
        id: newId(),
        orgId,
        recipientId: input.recipientId,
        kind: input.kind,
        title: input.title,
        body: input.body,
        href: input.href,
        actorId: input.actorId,
        readAt: null,
        channels: JSON.stringify(input.channels),
        createdAt: stamp,
        updatedAt: stamp,
      })),
    )
    .returning()
    .all();

  return rows.map(toNotification);
}

export async function markRead(
  orgId: OrgId,
  notificationId: NotificationId,
  at: IsoTimestamp,
): Promise<Notification> {
  const row = getDb()
    .update(notifications)
    .set({ readAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(notifications.orgId, orgId),
        eq(notifications.id, notificationId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Notification ${notificationId} not found`);
  return toNotification(row);
}

export async function markAllRead(
  orgId: OrgId,
  recipientId: UserId,
  at: IsoTimestamp,
): Promise<number> {
  const rows = getDb()
    .update(notifications)
    .set({ readAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(notifications.orgId, orgId),
        eq(notifications.recipientId, recipientId),
        isNull(notifications.readAt),
      ),
    )
    .returning({ id: notifications.id })
    .all();

  return rows.length;
}

/** The digest window query: everything still unread since `since`. */
export async function listUnreadSince(
  orgId: OrgId,
  recipientId: UserId,
  since: IsoTimestamp,
): Promise<readonly Notification[]> {
  const rows = getDb()
    .select()
    .from(notifications)
    .where(
      and(
        orgPredicate(notifications.orgId, orgId),
        eq(notifications.recipientId, recipientId),
        isNull(notifications.readAt),
        gte(notifications.createdAt, since),
      ),
    )
    .orderBy(desc(notifications.createdAt))
    .all();

  return rows.map(toNotification);
}

/**
 * Pending invitations, keyed by token hash for the unauthenticated accept flow.
 */
import { and, count, desc, eq, isNull } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, invitations } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toInvitation } from "./_mappers";
import type { CreateInvitationInput } from "@/schemas/invitation";
import type { InvitationId, IsoTimestamp, OrgId, UserId } from "@/types/common";
import type { Invitation } from "@/types/member";

/**
 * Unit behind `expiresInDays`. Invite links are short-lived credentials, so
 * the schema's whole-number validity is applied per hour rather than per day.
 */
const EXPIRY_UNIT_MS = 60 * 60 * 1000;

export async function insertInvitation(
  orgId: OrgId,
  input: CreateInvitationInput,
  invitedBy: UserId,
  tokenHash: string,
): Promise<Invitation> {
  const stamp = toIsoTimestamp(new Date());
  const expiresAt = toIsoTimestamp(
    new Date(Date.now() + input.expiresInDays * EXPIRY_UNIT_MS),
  );

  const row = getDb()
    .insert(invitations)
    .values({
      id: newId(),
      orgId,
      email: input.email,
      role: input.role,
      invitedBy,
      tokenHash,
      expiresAt,
      acceptedAt: null,
      revokedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toInvitation(row);
}

/**
 * The accept flow runs before a session exists, so this is the one read in the
 * repository layer that is not scoped by `orgId` — the token hash is the
 * credential and carries the tenant with it.
 */
export async function findInvitationByTokenHash(
  tokenHash: string,
): Promise<Invitation | null> {
  const row = getDb()
    .select()
    .from(invitations)
    .where(eq(invitations.tokenHash, tokenHash))
    .get();
  return row ? toInvitation(row) : null;
}

export async function listPendingInvitations(
  orgId: OrgId,
): Promise<readonly Invitation[]> {
  const rows = getDb()
    .select()
    .from(invitations)
    .where(
      and(
        orgPredicate(invitations.orgId, orgId),
        isNull(invitations.acceptedAt),
        isNull(invitations.revokedAt),
      ),
    )
    .orderBy(desc(invitations.createdAt))
    .all();

  return rows.map(toInvitation);
}

export async function markInvitationAccepted(
  orgId: OrgId,
  invitationId: InvitationId,
  at: IsoTimestamp,
): Promise<Invitation> {
  const row = getDb()
    .update(invitations)
    .set({ acceptedAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(invitations.orgId, orgId),
        eq(invitations.id, invitationId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Invitation ${invitationId} not found`);
  return toInvitation(row);
}

export async function revokeInvitation(
  orgId: OrgId,
  invitationId: InvitationId,
): Promise<Invitation> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .update(invitations)
    .set({ revokedAt: stamp, updatedAt: stamp })
    .where(
      and(
        orgPredicate(invitations.orgId, orgId),
        eq(invitations.id, invitationId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Invitation ${invitationId} not found`);
  return toInvitation(row);
}

/**
 * Pending invites hold a seat, so the seat quota counts them. An unaccepted
 * row keeps its seat whether or not it was withdrawn — a revoke-and-reinvite
 * loop must not be a way of queueing more people than the plan allows.
 */
export async function countPendingInvitations(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(invitations)
    .where(
      and(
        orgPredicate(invitations.orgId, orgId),
        isNull(invitations.acceptedAt),
      ),
    )
    .get();
  return row?.value ?? 0;
}

