/**
 * Pending invitations, keyed by token hash for the unauthenticated accept flow.
 */
import { and, count, desc, eq, gt, isNull, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, invitations } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toInvitation } from "./_mappers";
import type { CreateInvitationInput } from "@/schemas/invitation";
import type { InvitationId, IsoTimestamp, OrgId, UserId } from "@/types/common";
import type { Invitation } from "@/types/member";

/**
 * Unit behind `expiresInDays`.
 */
const EXPIRY_UNIT_MS = 24 * 60 * 60 * 1000;

export async function insertInvitation(
  orgId: OrgId,
  input: CreateInvitationInput,
  invitedBy: UserId,
  tokenHash: string,
): Promise<Invitation> {
  const stamp = toIsoTimestamp(new Date());
  const expiresAt = toIsoTimestamp(
    new Date(Date.now() + input.expiresInDays * EXPIRY_UNIT_MS),
  );

  const row = getDb()
    .insert(invitations)
    .values({
      id: newId(),
      orgId,
      email: input.email.toLowerCase(),
      role: input.role,
      invitedBy,
      tokenHash,
      expiresAt,
      acceptedAt: null,
      revokedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toInvitation(row);
}

/**
 * The accept flow runs before a session exists, so this is the one read in the
 * repository layer that is not scoped by `orgId` — the token hash is the
 * credential and carries the tenant with it.
 */
export async function findInvitationByTokenHash(
  tokenHash: string,
): Promise<Invitation | null> {
  const row = getDb()
    .select()
    .from(invitations)
    .where(eq(invitations.tokenHash, tokenHash))
    .get();
  return row ? toInvitation(row) : null;
}

export async function findInvitationById(
  orgId: OrgId,
  invitationId: InvitationId,
): Promise<Invitation | null> {
  const row = getDb()
    .select()
    .from(invitations)
    .where(
      and(
        orgPredicate(invitations.orgId, orgId),
        eq(invitations.id, invitationId),
      ),
    )
    .get();
  return row ? toInvitation(row) : null;
}

export async function listPendingInvitations(
  orgId: OrgId,
): Promise<readonly Invitation[]> {
  const now = toIsoTimestamp(new Date());
  const rows = getDb()
    .select()
    .from(invitations)
    .where(
      and(
        orgPredicate(invitations.orgId, orgId),
        isNull(invitations.acceptedAt),
        isNull(invitations.revokedAt),
        gt(invitations.expiresAt, now),
      ),
    )
    .orderBy(desc(invitations.createdAt))
    .all();

  return rows.map(toInvitation);
}

/** Unaccepted invitation history, including expired and revoked rows. */
export async function listUnacceptedInvitations(
  orgId: OrgId,
): Promise<readonly Invitation[]> {
  const rows = getDb()
    .select()
    .from(invitations)
    .where(
      and(
        orgPredicate(invitations.orgId, orgId),
        isNull(invitations.acceptedAt),
      ),
    )
    .orderBy(desc(invitations.createdAt))
    .all();
  return rows.map(toInvitation);
}

export async function findPendingInvitationForEmail(
  orgId: OrgId,
  email: string,
  excludingId?: InvitationId,
): Promise<Invitation | null> {
  const now = toIsoTimestamp(new Date());
  const row = getDb()
    .select()
    .from(invitations)
    .where(
      and(
        orgPredicate(invitations.orgId, orgId),
        sql`lower(${invitations.email}) = ${email.toLowerCase()}`,
        isNull(invitations.acceptedAt),
        isNull(invitations.revokedAt),
        gt(invitations.expiresAt, now),
        excludingId === undefined
          ? undefined
          : sql`${invitations.id} <> ${excludingId}`,
      ),
    )
    .get();
  return row ? toInvitation(row) : null;
}

export async function markInvitationAccepted(
  orgId: OrgId,
  invitationId: InvitationId,
  at: IsoTimestamp,
): Promise<Invitation> {
  const row = getDb()
    .update(invitations)
    .set({ acceptedAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(invitations.orgId, orgId),
        eq(invitations.id, invitationId),
        isNull(invitations.acceptedAt),
        isNull(invitations.revokedAt),
        gt(invitations.expiresAt, at),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Invitation ${invitationId} not found`);
  return toInvitation(row);
}

export async function revokeInvitation(
  orgId: OrgId,
  invitationId: InvitationId,
): Promise<Invitation> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .update(invitations)
    .set({ revokedAt: stamp, updatedAt: stamp })
    .where(
      and(
        orgPredicate(invitations.orgId, orgId),
        eq(invitations.id, invitationId),
        isNull(invitations.acceptedAt),
        isNull(invitations.revokedAt),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Invitation ${invitationId} not found`);
  return toInvitation(row);
}

/**
 * Only live invitations hold a seat. Revoked, accepted, and expired rows do
 * not consume capacity.
 */
export async function countPendingInvitations(orgId: OrgId): Promise<number> {
  const now = toIsoTimestamp(new Date());
  const row = getDb()
    .select({ value: count() })
    .from(invitations)
    .where(
      and(
        orgPredicate(invitations.orgId, orgId),
        isNull(invitations.acceptedAt),
        isNull(invitations.revokedAt),
        gt(invitations.expiresAt, now),
      ),
    )
    .get();
  return row?.value ?? 0;
}

/**
 * Invite issuing and acceptance. Enforces the seat quota and the invite rate limit before a token is minted.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, wouldExceedLimit, getPlanLimits, consumeRateLimit
 */
import { getPlanLimits, wouldExceedLimit } from "@/config/plan-limits";
import { emit } from "@/lib/event-bus";
import { hashToken, randomToken } from "@/lib/hash";
import { assertCan } from "@/lib/permissions";
import { consumeRateLimit } from "@/lib/rate-limit";
import { assertOrgScope } from "@/lib/tenant";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as userRepo from "@/server/repositories/user-repository";
import { toIsoTimestamp } from "@/types/common";
import { envelope, orgResource, requireFound } from "./_support";
import type { AcceptInvitationTokenInput } from "@/schemas/invitation";
import type { InviteMemberInput, InviteMembersInput } from "@/schemas/member";
import type { InvitationId, UserId } from "@/types/common";
import type { Actor, Invitation, Member } from "@/types/member";

/** Token bucket protecting the invite mailer from being used as a spam relay. */
const INVITE_BUCKET = "member:invite";

/** Default validity of a freshly minted invitation, in days. */
const DEFAULT_EXPIRY_DAYS = 14;

export async function inviteMember(
  actor: Actor,
  input: InviteMemberInput,
): Promise<Invitation> {
  const [invitation] = await inviteMembers(actor, {
    orgId: input.orgId,
    invites: [{ email: input.email, role: input.role }],
  });

  if (!invitation) throw new Error("Invitation was not created");
  return invitation;
}

/**
 * Bulk invite. The seat quota is checked once for the whole batch — inviting
 * five people into a plan with three free seats must fail as a batch rather
 * than half-succeeding — and the rate limit is charged per invite.
 */
export async function inviteMembers(
  actor: Actor,
  input: InviteMembersInput,
): Promise<readonly Invitation[]> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "member:invite", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  if (org.archivedAt !== null) {
    throw new Error("This organization has been deleted");
  }

  const normalizedInvites = input.invites.map((invite) => ({
    email: invite.email.trim().toLowerCase(),
    role: invite.role,
  }));
  const batchEmails = new Set<string>();
  for (const invite of normalizedInvites) {
    if (batchEmails.has(invite.email)) {
      throw new Error(`The invitation batch contains ${invite.email} more than once`);
    }
    batchEmails.add(invite.email);
  }

  for (const invite of normalizedInvites) {
    const [member, pendingInvitation] = await Promise.all([
      memberRepo.findMemberByEmail(input.orgId, invite.email),
      invitationRepo.findPendingInvitationForEmail(input.orgId, invite.email),
    ]);
    if (member) {
      throw new Error(`${invite.email} is already a member of this organization`);
    }
    if (pendingInvitation) {
      throw new Error(`${invite.email} already has a pending invitation`);
    }
  }

  const seatsUsed =
    (await memberRepo.countActiveMembers(input.orgId)) +
    (await invitationRepo.countPendingInvitations(input.orgId));

  if (
    wouldExceedLimit(org.plan, "seats", seatsUsed, normalizedInvites.length)
  ) {
    const limits = getPlanLimits(org.plan);
    throw new Error(
      `Plan ${org.plan} includes ${limits.seats} seats and ${seatsUsed} are taken`,
    );
  }

  const verdict = await consumeRateLimit(
    input.orgId,
    INVITE_BUCKET,
    normalizedInvites.length,
  );
  if (!verdict.allowed) {
    throw new Error(
      `Invite rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  return issueInvitations(actor, input.orgId, normalizedInvites);
}

/**
 * Accepting runs unauthenticated: the token is the credential, so there is no
 * `Actor` to scope against and every check has to come off the stored row.
 */
export async function acceptInvitation(
  userId: UserId,
  input: AcceptInvitationTokenInput,
): Promise<Member> {
  const invitation = requireFound(
    await invitationRepo.findInvitationByTokenHash(hashToken(input.token)),
    "Invitation",
    "token",
  );

  if (invitation.revokedAt !== null) {
    throw new Error("That invitation has been revoked");
  }
  if (invitation.acceptedAt !== null) {
    throw new Error("That invitation has already been accepted");
  }
  if (invitation.expiresAt <= toIsoTimestamp(new Date())) {
    throw new Error("That invitation has expired");
  }

  const org = await orgRepo.findOrgById(invitation.orgId);
  if (!org || org.archivedAt !== null) {
    throw new Error("That invitation belongs to a deleted organization");
  }

  const user = requireFound(
    await userRepo.findUserById(userId),
    "User",
    userId,
  );
  if (user.email.toLowerCase() !== invitation.email.toLowerCase()) {
    throw new Error("This invitation was sent to a different email address");
  }

  const acceptedAt = toIsoTimestamp(new Date());
  const existing = await memberRepo.findMemberIncludingArchived(
    invitation.orgId,
    userId,
  );
  if (existing && existing.archivedAt === null && existing.status === "active") {
    await invitationRepo.markInvitationAccepted(
      invitation.orgId,
      invitation.id,
      acceptedAt,
    );
    return existing;
  }

  const member = existing
    ? await memberRepo.restoreMember(
        invitation.orgId,
        userId,
        invitation.role,
        invitation.invitedBy,
        acceptedAt,
      )
    : await memberRepo.insertMember(
        invitation.orgId,
        userId,
        invitation.role,
        invitation.invitedBy,
        acceptedAt,
      );

  await invitationRepo.markInvitationAccepted(
    invitation.orgId,
    invitation.id,
    acceptedAt,
  );

  await emit("member.joined", {
    ...envelope(invitation.orgId, userId),
    memberId: member.id,
    userId,
    role: member.role,
  });

  return member;
}

export async function revokeInvitation(
  actor: Actor,
  invitationId: InvitationId,
): Promise<Invitation> {
  assertCan(actor, "member:invite", orgResource(actor.orgId));
  const invitation = await invitationRepo.revokeInvitation(
    actor.orgId,
    invitationId,
  );
  await usageRepo.getUsage(actor.orgId);
  return invitation;
}

/**
 * Re-issuing preserves the invitation's role and address while replacing its
 * token and expiry. Expired invitations may be re-sent as well.
 */
export async function resendInvitation(
  actor: Actor,
  invitationId: InvitationId,
): Promise<Invitation> {
  assertOrgScope(actor, actor.orgId);
  assertCan(actor, "member:invite", orgResource(actor.orgId));

  const previous = requireFound(
    await invitationRepo.findInvitationById(actor.orgId, invitationId),
    "Invitation",
    invitationId,
  );
  if (previous.acceptedAt !== null) {
    throw new Error("An accepted invitation cannot be re-sent");
  }

  const email = previous.email.toLowerCase();
  if (await memberRepo.findMemberByEmail(actor.orgId, email)) {
    throw new Error(`${email} is already a member of this organization`);
  }
  if (
    await invitationRepo.findPendingInvitationForEmail(
      actor.orgId,
      email,
      previous.id,
    )
  ) {
    throw new Error(`${email} already has a pending invitation`);
  }

  const org = requireFound(
    await orgRepo.findOrgById(actor.orgId),
    "Organization",
    actor.orgId,
  );
  if (org.archivedAt !== null) {
    throw new Error("This organization has been deleted");
  }

  const wasPending =
    previous.revokedAt === null &&
    previous.expiresAt > toIsoTimestamp(new Date());
  const seatsUsed =
    (await memberRepo.countActiveMembers(actor.orgId)) +
    (await invitationRepo.countPendingInvitations(actor.orgId)) -
    (wasPending ? 1 : 0);
  if (wouldExceedLimit(org.plan, "seats", seatsUsed, 1)) {
    const limits = getPlanLimits(org.plan);
    throw new Error(
      `Plan ${org.plan} includes ${limits.seats} seats and ${seatsUsed} are taken`,
    );
  }

  const verdict = await consumeRateLimit(actor.orgId, INVITE_BUCKET);
  if (!verdict.allowed) {
    throw new Error(
      `Invite rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  if (previous.revokedAt === null) {
    await invitationRepo.revokeInvitation(actor.orgId, invitationId);
  }

  const [invitation] = await issueInvitations(actor, actor.orgId, [
    { email, role: previous.role },
  ]);
  if (!invitation) throw new Error("Invitation was not created");
  return invitation;
}

async function issueInvitations(
  actor: Actor,
  orgId: Invitation["orgId"],
  invites: readonly { email: string; role: Invitation["role"] }[],
): Promise<readonly Invitation[]> {
  const created: Invitation[] = [];
  for (const invite of invites) {
    const token = randomToken(32);
    const invitation = await invitationRepo.insertInvitation(
      orgId,
      {
        orgId,
        email: invite.email,
        role: invite.role,
        expiresInDays: DEFAULT_EXPIRY_DAYS,
      },
      actor.userId,
      hashToken(token),
    );
    created.push(invitation);

    await emit("member.invited", {
      orgId,
      actorId: actor.userId,
      occurredAt: invitation.createdAt,
      email: invitation.email,
      role: invitation.role,
    });
  }

  await usageRepo.getUsage(orgId);
  return created;
}

